window.bookSummaryJSON = "<p>A notorious lady learns just how wicked a good man can be in the latest installment of RITA Award nominee Julie Anne Long's emotionally charged Pennyroyal Green series. </p> <p>The breathtaking romantic adventures of a former courtesan-turned-noblewoman, <i>A Notorious Countess Confesses</i> stokes the Pennyroyal fires hotter than ever before, providing listeners with all the passion, scandal, and true love they could possibly hope for.</p> <p><b>Contains mature themes.</b></p>"; 
